func lunafoxProjectConfig(config *engineexecutionpb.EngineExecutionConfig) (enginecontract.Config, error) {
	if config == nil || len(config.GetSections()) != 3 {
		return enginecontract.Config{}, errors.New("Engine config sections do not match the Engine Definition")
	}
	var projected enginecontract.Config
	var seenRecon bool
	var seenBruteforce bool
	var seenResolve bool
	for _, section := range config.GetSections() {
		if section == nil {
			return enginecontract.Config{}, errors.New("Engine config section is required")
		}
		switch section.GetSectionId() {
		case "recon":
			if seenRecon {
				return enginecontract.Config{}, errors.New("duplicate Engine config section")
			}
			seenRecon = true
			value, err := lunafoxProjectReconConfig(section)
			if err != nil {
				return enginecontract.Config{}, err
			}
			projected.Recon = value
		case "bruteforce":
			if seenBruteforce {
				return enginecontract.Config{}, errors.New("duplicate Engine config section")
			}
			seenBruteforce = true
			value, err := lunafoxProjectBruteforceConfig(section)
			if err != nil {
				return enginecontract.Config{}, err
			}
			projected.Bruteforce = value
		case "resolve":
			if seenResolve {
				return enginecontract.Config{}, errors.New("duplicate Engine config section")
			}
			seenResolve = true
			value, err := lunafoxProjectResolveConfig(section)
			if err != nil {
				return enginecontract.Config{}, err
			}
			projected.Resolve = value
		default:
			return enginecontract.Config{}, errors.New("Engine config contains an undeclared section")
		}
	}
	if !seenRecon {
		return enginecontract.Config{}, errors.New("Engine config is missing a declared section")
	}
	if !seenBruteforce {
		return enginecontract.Config{}, errors.New("Engine config is missing a declared section")
	}
	if !seenResolve {
		return enginecontract.Config{}, errors.New("Engine config is missing a declared section")
	}
	return projected, nil
}

