func lunafoxProjectConfigResources(resources []*engineexecutionpb.ConfigResource, config *enginecontract.Config) error {
	if config == nil {
		return errors.New("Engine config resources do not match the Engine Definition")
	}
	var seenBruteforceWordlist bool
	var seenBruteforceResolvers bool
	var seenResolveResolvers bool
	for _, resource := range resources {
		if resource == nil || resource.GetPath() == "" || resource.GetContentType() == "" {
			return errors.New("complete Engine config resource binding is required")
		}
		switch {
		case resource.GetSectionId() == "bruteforce" && resource.GetParamKey() == "wordlist":
			if !config.Bruteforce.Enabled {
				return errors.New("Engine config resource binding is forbidden for a disabled section")
			}
			if seenBruteforceWordlist {
				return errors.New("duplicate Engine config resource binding")
			}
			seenBruteforceWordlist = true
			config.Bruteforce.Wordlist = resource.GetPath()
		case resource.GetSectionId() == "bruteforce" && resource.GetParamKey() == "resolvers":
			if !config.Bruteforce.Enabled {
				return errors.New("Engine config resource binding is forbidden for a disabled section")
			}
			if seenBruteforceResolvers {
				return errors.New("duplicate Engine config resource binding")
			}
			seenBruteforceResolvers = true
			config.Bruteforce.Resolvers = resource.GetPath()
		case resource.GetSectionId() == "resolve" && resource.GetParamKey() == "resolvers":
			if !config.Resolve.Enabled {
				return errors.New("Engine config resource binding is forbidden for a disabled section")
			}
			if seenResolveResolvers {
				return errors.New("duplicate Engine config resource binding")
			}
			seenResolveResolvers = true
			config.Resolve.Resolvers = resource.GetPath()
		default:
			return errors.New("Engine config contains an undeclared resource binding")
		}
	}
	if config.Bruteforce.Enabled && !seenBruteforceWordlist {
		return errors.New("Engine config is missing a declared resource binding")
	}
	if config.Bruteforce.Enabled && !seenBruteforceResolvers {
		return errors.New("Engine config is missing a declared resource binding")
	}
	if config.Resolve.Enabled && !seenResolveResolvers {
		return errors.New("Engine config is missing a declared resource binding")
	}
	return nil
}

func lunafoxProjectPlatformResources(resources []*engineexecutionpb.PlatformResource) (enginecontract.PlatformResources, error) {
	if len(resources) != 1 {
		return enginecontract.PlatformResources{}, errors.New("Engine platform resources do not match the Engine Definition")
	}
	var projected enginecontract.PlatformResources
	var seenSubfinderProviderConfig bool
	for _, resource := range resources {
		if resource == nil || resource.GetPath() == "" || resource.GetContentType() == "" {
			return enginecontract.PlatformResources{}, errors.New("complete Engine platform resource binding is required")
		}
		switch resource.GetResourceId() {
		case "subfinderProviderConfig":
			if seenSubfinderProviderConfig {
				return enginecontract.PlatformResources{}, errors.New("duplicate Engine platform resource binding")
			}
			seenSubfinderProviderConfig = true
			projected.SubfinderProviderConfig = resource.GetPath()
		default:
			return enginecontract.PlatformResources{}, errors.New("Engine platform resource is not declared by this Engine")
		}
	}
	if !seenSubfinderProviderConfig {
		return enginecontract.PlatformResources{}, errors.New("Engine platform resource is missing")
	}
	return projected, nil
}
